    enonce: "<span dir=\"ltr\" class=\"expr pt\">M</span> حجر منتصب <span dir=\"ltr\" class=\"expr\">(</span>منهير<span dir=\"ltr\" class=\"expr\">)</span> يتعذّر الوصول إليه.<br>النّقط <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> و <span dir=\"ltr\" class=\"expr pt\">A</span> على استقامة واحدة، و كذلك <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">D</span> و <span dir=\"ltr\" class=\"expr pt\">B</span>،<br>و <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span> حيث <span dir=\"ltr\" class=\"expr pt\">CD = 8,4 m</span> و <span dir=\"ltr\" class=\"expr pt\">AB = 42 m</span> و <span dir=\"ltr\" class=\"expr pt\">CA = 40,32 m.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 258 193\" width=\"258\" height=\"193\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(3.7 8.2)\"><line x1=\"20.7\" y1=\"159.8\" x2=\"229.3\" y2=\"159.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"20.7\" y1=\"159.8\" x2=\"125.0\" y2=\"20.7\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"229.3\" y1=\"159.8\" x2=\"125.0\" y2=\"20.7\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"62.4\" y1=\"159.8\" x2=\"41.6\" y2=\"132.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"20.7\" cy=\"159.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"7.0\" y=\"169.9\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">M</text><circle cx=\"229.3\" cy=\"159.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"243.9\" y=\"167.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"125.0\" cy=\"20.7\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"129.0\" y=\"10.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"62.4\" cy=\"159.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"51.8\" y=\"174.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"41.6\" cy=\"132.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"26.6\" y=\"137.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 8,4</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 42</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 40,32</span>  و  <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>"},{"quoi":"1)","math":"أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">CM.</span> نختار النّسبة و الجزء الباقي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">42</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 42</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">1008</span><span class=\"den\">25</span></span>. و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"القاعدة","math":"إذا عُلمت النّسبة و عُلم الجزء الباقي، أمكن حساب الطولين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 8,4</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 42</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 40,32</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CM =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">25</span></span>  ، لأنّ النّسبة <span class=\"frac\" dir=\"ltr\"><span class=\"num\">8,4</span><span class=\"den\">42</span></span> و الفرق 40,32"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">25</span></span>"},{"quoi":"2)","math":"استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AM.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">42</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 42</span>  و  <span dir=\"ltr\" class=\"expr pt\">CM =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">25</span></span>. و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">8,4</span><span class=\"den\">42</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\"><span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">25</span></span><span dir=\"ltr\" class=\"expr pt\">&lt;/span&gt;&lt;span class=\"den\"&gt;AM&lt;/span&gt;&lt;/span&gt;</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">252</span><span class=\"den\">5</span></span>"}],
